    84	</head>
    85	<body>
    86	<main>
    87	  <h1>Todos</h1>
    88	  <form id="todo-form" autocomplete="off">
    89	    <input type="text" data-testid="todo-input" id="todo-input" placeholder="What needs doing?" aria-label="New todo">
    90	    <input type="date" data-testid="todo-due" id="todo-due" aria-label="Due date (optional)">
    91	    <select data-testid="todo-priority" id="todo-priority" aria-label="Priority">
    92	      <option value="low">Low</option>
    93	      <option value="med" selected>Med</option>
    94	      <option value="high">High</option>
    95	    </select>
    96	    <button type="submit" class="add" data-testid="todo-add">Add</button>
    97	  </form>
    98	  <input type="search" class="search" data-testid="search-input" id="search-input" placeholder="Search" aria-label="Search todos">
    99	  <div class="filters" role="group" aria-label="Show">
   100	    <button type="button" class="filter" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
   101	    <button type="button" class="filter" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
   102	    <button type="button" class="filter" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
   103	  </div>
   104	  <ul data-testid="todo-list" id="todo-list"></ul>
   105	  <p class="empty" id="empty">Nothing here yet.</p>
   106	  <div class="bulk" role="group" aria-label="Bulk actions">
   107	    <button type="button" class="bulk-action" data-testid="bulk-mark-all" id="bulk-mark-all">Mark all complete</button>
   108	    <button type="button" class="bulk-action" data-testid="bulk-clear-completed" id="bulk-clear-completed">Clear completed</button>
   109	  </div>
   110	</main>
   111	<script>
   112	(function () {
   113	  var STORAGE_KEY = 'todos';
   114	
   115	  var form = document.getElementById('todo-form');
   116	  var input = document.getElementById('todo-input');
   117	  var dueInput = document.getElementById('todo-due');
   118	  var priorityInput = document.getElementById('todo-priority');
   119	  var list = document.getElementById('todo-list');
   120	  var empty = document.getElementById('empty');
   121	  var filterButtons = document.querySelectorAll('[data-filter]');
   122	  var searchInput = document.getElementById('search-input');
   123	  var markAllButton = document.getElementById('bulk-mark-all');
   124	  var clearCompletedButton = document.getElementById('bulk-clear-completed');
   125	
   126	  var filter = 'all';
   127	  var search = '';
   128	
   129	  function load() {
   130	    try {
   131	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
   132	      return Array.isArray(data) ? data : [];
   133	    } catch (e) {
   134	      return [];
   135	    }
   136	  }
   137	
   138	  function save() {
   139	    try {
   140	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
   141	    } catch (e) {
   142	      // Storage unavailable or full; keep working in memory.
   143	    }
   144	  }
   145	
   146	  function newId() {
   147	    if (window.crypto && typeof crypto.randomUUID === 'function') {
   148	      return crypto.randomUUID();
   149	    }
   150	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
   151	  }
   152	
   153	  var todos = load();
   154	
   155	  // Date rule (project decision): a due date is stored as a plain "YYYY-MM-DD"
   156	  // string and means a LOCAL calendar date. Never pass it through Date parsing
   157	  // or UTC (new Date("YYYY-MM-DD") is UTC midnight and shifts the day).
   158	  // Overdue = due date strictly before today's local date; date-only, so a
   159	  // todo due today is never overdue. Zero-padded strings compare correctly as text.
   160	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
   161	
   162	  function pad(n) {
   163	    return (n < 10 ? '0' : '') + n;
   164	  }
   165	
   166	  function todayLocal() {
   167	    var now = new Date();
   168	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
   169	  }
   170	
   171	  function validDue(value) {
   172	    return typeof value === 'string' && DATE_RE.test(value) ? value : null;
   173	  }
   174	
   175	  function isOverdue(todo) {
   176	    var due = validDue(todo.due);
   177	    return due !== null && due < todayLocal();
   178	  }
   179	
   180	  // Priority rule: one of "low", "med", "high". Anything else (including todos
   181	  // saved before priorities existed) is treated as "med".
   182	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
   183	
   184	  function validPriority(value) {
   185	    return PRIORITY_LABELS.hasOwnProperty(value) ? value : 'med';
   186	  }
   187	
   188	  function formatDue(due) {
   189	    var parts = due.split('-');
   190	    var year = Number(parts[0]);
   191	    var date = new Date(year, Number(parts[1]) - 1, Number(parts[2])); // Local date.
   192	    var options = { month: 'short', day: 'numeric' };
   193	    if (year !== new Date().getFullYear()) options.year = 'numeric';
   194	    return date.toLocaleDateString(undefined, options);
   195	  }
   196	
   197	  // Ordering rule (project decision): completed todos always appear below all
   198	  // active todos. Within each group, todos are sorted by priority (high, med,
   199	  // low); within the same priority they stay in insertion order (oldest first).
   200	  // `todos` is kept in insertion order; the index tiebreak keeps the sort stable.
   201	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
   202	
   203	  function byPriority(group) {
   204	    return group
   205	      .map(function (t, i) { return { todo: t, index: i }; })
   206	      .sort(function (a, b) {
   207	        return PRIORITY_RANK[validPriority(a.todo.priority)] - PRIORITY_RANK[validPriority(b.todo.priority)] ||
   208	          a.index - b.index;
   209	      })
   210	      .map(function (entry) { return entry.todo; });
   211	  }
   212	
   213	  function ordered() {
   214	    var active = todos.filter(function (t) { return !t.completed; });
   215	    var completed = todos.filter(function (t) { return t.completed; });
   216	    return byPriority(active).concat(byPriority(completed));
   217	  }
   218	
   219	  // Search is a case-insensitive substring match on the text, applied on top
   220	  // of the active filter.
   221	  function matchesSearch(todo) {
   222	    return String(todo.text).toLowerCase().indexOf(search.toLowerCase()) !== -1;
   223	  }
   224	
   225	  function visible() {
   226	    return ordered().filter(function (t) {
   227	      if (filter === 'active' && t.completed) return false;
   228	      if (filter === 'completed' && !t.completed) return false;
   229	      return matchesSearch(t);
   230	    });
   231	  }
   232	
   233	  // Rows are kept by id and reused across renders, so a checkbox the user just
   234	  // clicked stays the same element after the list is reordered or filtered.
   235	  var rows = {};
   236	
   237	  function createRow(todo) {
   238	    var li = document.createElement('li');
   239	    li.setAttribute('data-testid', 'todo-item');
   240	    li.setAttribute('data-id', todo.id);
   241	
   242	    var toggle = document.createElement('input');
   243	    toggle.type = 'checkbox';
   244	    toggle.className = 'toggle';
   245	    toggle.setAttribute('data-testid', 'todo-toggle');
   246	    toggle.addEventListener('change', function () {
   247	      toggleTodo(todo.id);
   248	    });
   249	
   250	    var content = document.createElement('div');
   251	    content.className = 'content';
   252	
   253	    var text = document.createElement('span');
   254	    text.className = 'text';
   255	    text.setAttribute('data-testid', 'todo-text');
   256	    text.addEventListener('dblclick', function () {
   257	      startEdit(li, todo.id);
   258	    });
   259	
   260	    var due = document.createElement('time');
   261	    due.className = 'due';
   262	    due.setAttribute('data-testid', 'todo-due-date');
   263	
   264	    content.appendChild(text);
   265	    content.appendChild(due);
   266	
   267	    var priority = document.createElement('span');
   268	    priority.className = 'priority';
   269	
   270	    var del = document.createElement('button');
   271	    del.type = 'button';
   272	    del.className = 'delete';
   273	    del.setAttribute('data-testid', 'todo-delete');
   274	    del.textContent = 'Delete';
   275	    del.addEventListener('click', function () {
   276	      removeTodo(todo.id);
   277	    });
   278	
   279	    li.appendChild(toggle);
   280	    li.appendChild(content);
   281	    li.appendChild(priority);
   282	    li.appendChild(del);
   283	    return li;
   284	  }
   285	
   286	  // Inline editing: Enter or blur commits, Escape cancels. Committing empty
   287	  // text keeps the old text.
   288	  function startEdit(li, id) {
   289	    var todo = findTodo(id);
   290	    if (!todo || li.querySelector('.edit')) return;
   291	    var text = li.querySelector('.text');
   292	    var field = document.createElement('input');
   293	    field.type = 'text';
   294	    field.className = 'edit';
   295	    field.setAttribute('data-testid', 'todo-edit');
   296	    field.setAttribute('aria-label', 'Edit todo');
   297	    field.value = todo.text;
   298	
   299	    var finished = false;
   300	    function finish(commit) {
   301	      if (finished) return; // Removing the field can fire blur; handle once.
   302	      finished = true;
   303	      var value = field.value.trim();
   304	      if (field.parentNode) field.parentNode.removeChild(field);
   305	      text.hidden = false;
   306	      if (commit && value && value !== todo.text) editTodo(id, value);
   307	    }
   308	
   309	    field.addEventListener('keydown', function (event) {
   310	      if (event.key === 'Enter') {
   311	        event.preventDefault();
   312	        finish(true);
   313	      } else if (event.key === 'Escape') {
   314	        event.preventDefault();
   315	        finish(false);
   316	      }
   317	    });
   318	    field.addEventListener('blur', function () {
   319	      finish(true);
   320	    });
   321	
   322	    text.hidden = true;
   323	    text.parentNode.insertBefore(field, text);
   324	    field.focus();
   325	    field.setSelectionRange(field.value.length, field.value.length);
   326	  }
   327	
   328	  function render() {
   329	    var items = visible();
   330	    var keep = {};
   331	    var cursor = list.firstChild;
   332	
   333	    items.forEach(function (todo) {
   334	      var li = rows[todo.id] || (rows[todo.id] = createRow(todo));
   335	      var toggle = li.querySelector('.toggle');
   336	      li.querySelector('.text').textContent = todo.text;
   337	      li.querySelector('.delete').setAttribute('aria-label', 'Delete "' + todo.text + '"');
   338	      var dueLabel = li.querySelector('.due');
   339	      var due = validDue(todo.due);
   340	      var overdue = isOverdue(todo);
   341	      var priority = validPriority(todo.priority);
   342	      var priorityLabel = li.querySelector('.priority');
   343	      li.setAttribute('data-priority', priority);
   344	      priorityLabel.textContent = PRIORITY_LABELS[priority];
   345	      priorityLabel.setAttribute('aria-label', PRIORITY_LABELS[priority] + ' priority');
   346	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
   347	      li.setAttribute('data-overdue', overdue ? 'true' : 'false');
   348	      dueLabel.hidden = due === null;
   349	      if (due === null) {
   350	        dueLabel.removeAttribute('datetime');
   351	        dueLabel.textContent = '';
   352	      } else {
   353	        dueLabel.setAttribute('datetime', due);
   354	        dueLabel.textContent = (overdue ? 'Overdue \u00b7 ' : 'Due ') + formatDue(due);
   355	      }
   356	      toggle.checked = !!todo.completed;
   357	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" as ' + (todo.completed ? 'not done' : 'done'));
   358	      keep[todo.id] = true;
   359	      // Move a row only when it is out of place, so a row being edited keeps focus.
   360	      if (li === cursor) {
   361	        cursor = cursor.nextSibling;
   362	      } else {
   363	        list.insertBefore(li, cursor);
   364	      }
   365	    });
   366	
   367	    Object.keys(rows).forEach(function (id) {
   368	      if (keep[id]) return;
   369	      if (rows[id].parentNode) rows[id].parentNode.removeChild(rows[id]);
   370	      if (!todos.some(function (t) { return t.id === id; })) delete rows[id];
   371	    });
   372	
   373	    filterButtons.forEach(function (button) {
   374	      button.setAttribute('aria-pressed', button.getAttribute('data-filter') === filter ? 'true' : 'false');
   375	    });
   376	
   377	    if (todos.length === 0) {
   378	      empty.textContent = 'Nothing here yet.';
   379	    } else if (search) {
   380	      empty.textContent = 'No todos match \u201c' + search + '\u201d.';
   381	    } else if (filter === 'active') {
   382	      empty.textContent = 'All done.';
   383	    } else if (filter === 'completed') {
   384	      empty.textContent = 'Nothing completed yet.';
   385	    }
   386	    empty.hidden = items.length > 0;
   387	
   388	    // Bulk buttons stay clickable (a click with nothing to do is a no-op);
   389	    // data-idle only mutes them.
   390	    var hasActive = todos.some(function (t) { return !t.completed; });
   391	    var hasCompleted = todos.some(function (t) { return t.completed; });
   392	    markAllButton.setAttribute('data-idle', hasActive ? 'false' : 'true');
   393	    clearCompletedButton.setAttribute('data-idle', hasCompleted ? 'false' : 'true');
   394	  }
   395	
   396	  function addTodo(text, due, priority) {
   397	    todos.push({ id: newId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: validPriority(priority) });
   398	    save();
   399	    render();
   400	  }
   401	
   402	  function findTodo(id) {
   403	    for (var i = 0; i < todos.length; i++) {
   404	      if (todos[i].id === id) return todos[i];
   405	    }
   406	    return null;
   407	  }
   408	
   409	  function editTodo(id, text) {
   410	    var todo = findTodo(id);
   411	    if (!todo) return;
   412	    todo.text = text;
   413	    save();
   414	    render();
   415	  }
   416	
   417	  function removeTodo(id) {
   418	    todos = todos.filter(function (t) { return t.id !== id; });
   419	    save();
   420	    render();
   421	  }
   422	
   423	  function toggleTodo(id) {
   424	    todos.forEach(function (t) {
   425	      if (t.id === id) t.completed = !t.completed;
   426	    });
   427	    save();
   428	    render();
   429	  }
   430	
   431	  // Bulk actions apply to all todos, regardless of the current filter or search.
   432	  // They only change flags or remove items; `todos` keeps its insertion order,
   433	  // so render() applies the ordering rule as usual.
   434	  function markAllComplete() {
   435	    if (!todos.some(function (t) { return !t.completed; })) return;
   436	    todos.forEach(function (t) { t.completed = true; });
   437	    save();
   438	    render();
   439	  }
   440	
   441	  function clearCompleted() {
   442	    if (!todos.some(function (t) { return t.completed; })) return;
   443	    todos = todos.filter(function (t) { return !t.completed; });
   444	    save();
   445	    render();
   446	  }
   447	
   448	  function setFilter(value) {
   449	    filter = value;
   450	    render();
   451	  }
   452	
   453	  filterButtons.forEach(function (button) {
   454	    button.addEventListener('click', function () {
   455	      setFilter(button.getAttribute('data-filter'));
   456	    });
   457	  });
   458	
   459	  markAllButton.addEventListener('click', markAllComplete);
   460	  clearCompletedButton.addEventListener('click', clearCompleted);
   461	
   462	  searchInput.addEventListener('input', function () {
   463	    search = searchInput.value;
   464	    render();
   465	  });
   466	
   467	  form.addEventListener('submit', function (event) {
   468	    event.preventDefault();
   469	    var text = input.value.trim();
   470	    if (!text) return;
   471	    addTodo(text, validDue(dueInput.value), priorityInput.value);
   472	    input.value = '';
   473	    dueInput.value = '';
   474	    priorityInput.value = 'med';
   475	    input.focus();
   476	  });
   477	
   478	  // "Today" moves at local midnight; re-render so overdue flags stay current.
   479	  function scheduleMidnightRender() {
   480	    var now = new Date();
   481	    var next = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1);
   482	    setTimeout(function () {
   483	      render();
   484	      scheduleMidnightRender();
   485	    }, next - now + 1000);
   486	  }
   487	
   488	  document.addEventListener('visibilitychange', function () {
   489	    if (!document.hidden) render();
   490	  });
   491	
   492	  render();
   493	  scheduleMidnightRender();
   494	})();
   495	</script>
   496	</body>
   497	</html>
