// Keyboard shortcuts: Enter in the todo input adds (form submit), Escape
// cancels an inline edit (see startEdit), and "/" focuses search unless the
// user is already typing in a field.
function isTypingField(el) {
  if (!el || el === document.body) return false;
  if (el.isContentEditable) return true;
  var tag = el.tagName;
  if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
  if (tag !== 'INPUT') return false;
  return !/^(checkbox|radio|button|submit|reset|image|file|range|color)$/i.test(el.type);
}

document.addEventListener('keydown', function (event) {
  if (event.key !== '/' || event.ctrlKey || event.metaKey || event.altKey || event.isComposing) return;
  if (event.defaultPrevented || isTypingField(event.target)) return;
  event.preventDefault();
  searchInput.focus();
  searchInput.select();
});

