const { chromium } = require('/Users/vmysla/.npm/_npx/6bcb61ec6d5aea22/node_modules/playwright-core');
const assert = require('assert');
const URL = 'file:///Users/vmysla/src/product-tracebility-ab-testing/ab-study/arms/todo-rep-control-02/control/index.html';

let failures = 0;
async function t(name, fn) {
  try { await fn(); console.log('ok   ', name); }
  catch (e) { failures++; console.log('FAIL ', name, '\n      ', e.message.split('\n')[0]); }
}

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext();
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });

  const texts = () => page.$$eval('[data-testid=todo-text]', els => els.map(e => e.textContent));
  const stored = () => page.evaluate(() => JSON.parse(localStorage.getItem('todos')));
  const reset = async () => { await page.goto(URL); await page.evaluate(() => localStorage.clear()); await page.reload(); };
  const add = async (text, opts = {}) => {
    await page.fill('[data-testid=todo-input]', text);
    if (opts.due) await page.fill('[data-testid=todo-due]', opts.due);
    if (opts.priority) await page.selectOption('[data-testid=todo-priority]', opts.priority);
    await page.press('[data-testid=todo-input]', 'Enter');
  };
  const item = text => page.locator('[data-testid=todo-item]', { has: page.locator('[data-testid=todo-text]', { hasText: new RegExp('^' + text + '$') }) });

  await reset();

  // --- Shortcuts ---
  await t('Enter in todo input adds todo and clears input', async () => {
    await add('alpha');
    assert.deepStrictEqual(await texts(), ['alpha']);
    assert.strictEqual(await page.inputValue('[data-testid=todo-input]'), '');
    assert.strictEqual(await page.evaluate(() => document.activeElement.id), 'todo-input');
  });
  await t('Enter with blank input adds nothing', async () => {
    await page.fill('[data-testid=todo-input]', '   ');
    await page.press('[data-testid=todo-input]', 'Enter');
    assert.strictEqual((await texts()).length, 1);
  });
  await t('Add button still works', async () => {
    await page.fill('[data-testid=todo-input]', 'beta');
    await page.click('[data-testid=todo-add]');
    assert.deepStrictEqual(await texts(), ['alpha', 'beta']);
  });
  await t('/ focuses search from page body, without typing a slash', async () => {
    await page.evaluate(() => document.activeElement.blur());
    await page.keyboard.press('/');
    assert.strictEqual(await page.evaluate(() => document.activeElement.id), 'search-input');
    assert.strictEqual(await page.inputValue('[data-testid=search-input]'), '');
  });
  await t('/ typed in todo input stays in the input', async () => {
    await page.click('[data-testid=todo-input]');
    await page.keyboard.type('a/b');
    assert.strictEqual(await page.inputValue('[data-testid=todo-input]'), 'a/b');
    assert.strictEqual(await page.evaluate(() => document.activeElement.id), 'todo-input');
    await page.fill('[data-testid=todo-input]', '');
  });
  await t('/ typed in search box stays in search', async () => {
    await page.click('[data-testid=search-input]');
    await page.keyboard.type('x/');
    assert.strictEqual(await page.inputValue('[data-testid=search-input]'), 'x/');
    await page.fill('[data-testid=search-input]', '');
    await page.dispatchEvent('[data-testid=search-input]', 'input');
  });
  await t('/ works when a checkbox or button has focus', async () => {
    await page.focus('[data-testid=filter-all]');
    await page.keyboard.press('/');
    assert.strictEqual(await page.evaluate(() => document.activeElement.id), 'search-input');
    await item('alpha').locator('[data-testid=todo-toggle]').focus();
    await page.keyboard.press('/');
    assert.strictEqual(await page.evaluate(() => document.activeElement.id), 'search-input');
  });
  await t('/ typed in inline edit stays in the edit field', async () => {
    await item('alpha').locator('[data-testid=todo-text]').dblclick();
    await page.keyboard.type('/x');
    assert.strictEqual(await page.inputValue('[data-testid=todo-edit]'), 'alpha/x');
    await page.keyboard.press('Escape');
  });
  await t('Escape cancels inline edit and keeps old text', async () => {
    await item('alpha').locator('[data-testid=todo-text]').dblclick();
    await page.fill('[data-testid=todo-edit]', 'changed');
    await page.keyboard.press('Escape');
    assert.strictEqual(await page.locator('[data-testid=todo-edit]').count(), 0);
    assert.deepStrictEqual(await texts(), ['alpha', 'beta']);
    assert.deepStrictEqual((await stored()).map(x => x.text), ['alpha', 'beta']);
    assert.ok(await item('alpha').locator('[data-testid=todo-text]').isVisible());
  });

  // --- Earlier features ---
  await t('Inline edit: Enter commits', async () => {
    await item('alpha').locator('[data-testid=todo-text]').dblclick();
    await page.fill('[data-testid=todo-edit]', 'alpha2');
    await page.keyboard.press('Enter');
    assert.deepStrictEqual(await texts(), ['alpha2', 'beta']);
  });
  await t('Inline edit: blur commits; empty keeps old text', async () => {
    await item('alpha2').locator('[data-testid=todo-text]').dblclick();
    await page.fill('[data-testid=todo-edit]', 'alpha');
    await page.click('h1');
    assert.deepStrictEqual(await texts(), ['alpha', 'beta']);
    await item('alpha').locator('[data-testid=todo-text]').dblclick();
    await page.fill('[data-testid=todo-edit]', '  ');
    await page.keyboard.press('Enter');
    assert.deepStrictEqual(await texts(), ['alpha', 'beta']);
  });
  await t('Toggle completes and moves item below active ones', async () => {
    await item('alpha').locator('[data-testid=todo-toggle]').check();
    assert.deepStrictEqual(await texts(), ['beta', 'alpha']);
    assert.strictEqual(await item('alpha').getAttribute('data-completed'), 'true');
    assert.strictEqual((await stored()).find(x => x.text === 'alpha').completed, true);
  });
  await t('Persistence across reload', async () => {
    await page.reload();
    assert.deepStrictEqual(await texts(), ['beta', 'alpha']);
    assert.ok(await item('alpha').locator('[data-testid=todo-toggle]').isChecked());
  });
  await t('Filters: active / completed / all', async () => {
    await page.click('[data-testid=filter-active]');
    assert.deepStrictEqual(await texts(), ['beta']);
    assert.strictEqual(await page.getAttribute('[data-testid=filter-active]', 'aria-pressed'), 'true');
    await page.click('[data-testid=filter-completed]');
    assert.deepStrictEqual(await texts(), ['alpha']);
    await page.click('[data-testid=filter-all]');
    assert.deepStrictEqual(await texts(), ['beta', 'alpha']);
  });
  await t('Priority sort within groups, stable', async () => {
    await add('low1', { priority: 'low' });
    await add('high1', { priority: 'high' });
    await add('high2', { priority: 'high' });
    assert.strictEqual(await page.inputValue('[data-testid=todo-priority]'), 'med');
    assert.deepStrictEqual(await texts(), ['high1', 'high2', 'beta', 'low1', 'alpha']);
    assert.strictEqual(await item('high1').locator('.priority').textContent(), 'High');
  });
  await t('Due dates: overdue, today, future; stored as local YYYY-MM-DD', async () => {
    const d = await page.evaluate(() => {
      const f = x => x.getFullYear() + '-' + String(x.getMonth() + 1).padStart(2, '0') + '-' + String(x.getDate()).padStart(2, '0');
      const n = new Date();
      return { past: f(new Date(n.getFullYear(), n.getMonth(), n.getDate() - 1)), today: f(n) };
    });
    await add('late', { due: d.past });
    await add('now', { due: d.today });
    assert.strictEqual(await item('late').getAttribute('data-overdue'), 'true');
    assert.match(await item('late').locator('[data-testid=todo-due-date]').textContent(), /^Overdue/);
    assert.strictEqual(await item('now').getAttribute('data-overdue'), 'false');
    assert.strictEqual(await item('now').locator('[data-testid=todo-due-date]').getAttribute('datetime'), d.today);
    assert.strictEqual(await item('beta').locator('[data-testid=todo-due-date]').isVisible(), false);
    assert.strictEqual(await page.inputValue('[data-testid=todo-due]'), '');
    assert.strictEqual((await stored()).find(x => x.text === 'late').due, d.past);
  });
  await t('Search: case-insensitive, combined with filter, empty message', async () => {
    await page.fill('[data-testid=search-input]', 'HIGH');
    assert.deepStrictEqual(await texts(), ['high1', 'high2']);
    await page.click('[data-testid=filter-completed]');
    assert.deepStrictEqual(await texts(), []);
    assert.ok(await page.locator('#empty').isVisible());
    assert.match(await page.textContent('#empty'), /No todos match/);
    await page.click('[data-testid=filter-all]');
    await page.fill('[data-testid=search-input]', '');
    assert.strictEqual((await texts()).length, 7);
    assert.strictEqual(await page.locator('#empty').isVisible(), false);
  });
  await t('Delete removes item', async () => {
    await item('now').locator('[data-testid=todo-delete]').click();
    assert.ok(!(await texts()).includes('now'));
    assert.ok(!(await stored()).some(x => x.text === 'now'));
  });
  await t('Bulk: mark all complete ignores filter/search', async () => {
    await page.fill('[data-testid=search-input]', 'high');
    await page.click('[data-testid=bulk-mark-all]');
    await page.fill('[data-testid=search-input]', '');
    assert.ok((await stored()).every(x => x.completed));
    assert.strictEqual(await page.getAttribute('[data-testid=bulk-mark-all]', 'data-idle'), 'true');
  });
  await t('Bulk: clear completed', async () => {
    await add('keep');
    await page.click('[data-testid=bulk-clear-completed]');
    assert.deepStrictEqual(await texts(), ['keep']);
    assert.strictEqual(await page.getAttribute('[data-testid=bulk-clear-completed]', 'data-idle'), 'true');
  });
  await t('Empty state after deleting everything', async () => {
    await item('keep').locator('[data-testid=todo-delete]').click();
    assert.strictEqual(await page.textContent('#empty'), 'Nothing here yet.');
    assert.ok(await page.locator('#empty').isVisible());
  });
  await t('Edit a row while another row re-renders keeps the edit', async () => {
    await add('one'); await add('two');
    await item('two').locator('[data-testid=todo-text]').dblclick();
    await page.fill('[data-testid=todo-edit]', 'two-edited');
    await page.evaluate(() => document.dispatchEvent(new Event('visibilitychange')));
    assert.strictEqual(await page.evaluate(() => document.activeElement.dataset.testid), 'todo-edit');
    await page.keyboard.press('Enter');
    assert.deepStrictEqual(await texts(), ['one', 'two-edited']);
  });
  await t('Corrupt / legacy storage does not crash', async () => {
    await page.evaluate(() => localStorage.setItem('todos', '{bad'));
    await page.reload();
    assert.deepStrictEqual(await texts(), []);
    await page.evaluate(() => localStorage.setItem('todos', JSON.stringify([{ id: 'a', text: 'old', createdAt: 1 }])));
    await page.reload();
    assert.deepStrictEqual(await texts(), ['old']);
    assert.strictEqual(await item('old').locator('.priority').textContent(), 'Med');
  });
  await t('Narrow viewport: no horizontal scroll', async () => {
    await page.setViewportSize({ width: 360, height: 700 });
    await add('a fairly long todo text that should wrap nicely on a phone', { priority: 'high' });
    const over = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
    assert.strictEqual(over, false);
  });
  await t('No console or page errors', async () => {
    assert.deepStrictEqual(errors, []);
  });

  await browser.close();
  console.log(failures ? `\n${failures} failed` : '\nall passed');
  process.exit(failures ? 1 : 0);
})();

